{"content": "     1|/**
     2| * FPS 监控器
     3| * 使用 requestAnimationFrame 计算帧率
     4| */
     5|
     6|class FPSMonitor {
     7|  constructor() {
     8|    this.frames = 0
     9|    this.lastTime = performance.now()
    10|    this.fps = 60
    11|    this.running = false
    12|    this.rafId = null
    13|    this.onLowFPS = null
    14|    this.threshold = 30
    15|  }
    16|
    17|  start(onLowFPS, threshold = 30) {
    18|    if (this.running) return
    19|    this.running = true
    20|    this.onLowFPS = onLowFPS
    21|    this.threshold = threshold
    22|    this.lastTime = performance.now()
    23|    this.loop()
    24|  }
    25|
    26|  stop() {
    27|    this.running = false
    28|    if (this.rafId) {
    29|      cancelAnimationFrame(this.rafId)
    30|      this.rafId = null
    31|    }
    32|  }
    33|
    34|  loop() {
    35|    if (!this.running) return
    36|    this.frames++
    37|    const now = performance.now()
    38|    if (now >= this.lastTime + 1000) {
    39|      this.fps = Math.round((this.frames * 1000) / (now - this.lastTime))
    40|      this.frames = 0
    41|      this.lastTime = now
    42|      if (this.fps < this.threshold && this.onLowFPS) {
    43|        this.onLowFPS(this.fps)
    44|      }
    45|    }
    46|    this.rafId = requestAnimationFrame(() => this.loop())
    47|  }
    48|
    49|  getFPS() {
    50|    return this.fps
    51|  }
    52|
    53|  isRunning() {
    54|    return this.running
    55|  }
    56|}
    57|
    58|export const fpsMonitor = new FPSMonitor()
    59|export default fpsMonitor
